import struct
import json
import os
import re
import shutil

with open('/tmp/journal.copy', 'rb') as f:
    journal = f.read()

BLOCK_SIZE = 4096
num_blocks = len(journal) // BLOCK_SIZE

def is_valid_name(b):
    if not b or len(b) > 255 or b'\x00' in b or b'/' in b:
        return False
    try:
        s = b.decode('utf-8')
        return all(ord(c) >= 32 and ord(c) != 127 for c in s)
    except:
        return False

all_entries = {}
for b_idx in range(num_blocks):
    block = journal[b_idx*BLOCK_SIZE : (b_idx+1)*BLOCK_SIZE]
    pos = 0
    while pos + 8 <= len(block):
        ino, rlen, nlen, ft = struct.unpack('<IHBB', block[pos:pos+8])
        if rlen < 8 or rlen > 4096 or pos + rlen > len(block):
            break
        if nlen > 0 and 8 + nlen <= rlen and ft in (1, 2, 3, 4, 5, 6, 7):
            name_bytes = block[pos+8:pos+8+nlen]
            if is_valid_name(name_bytes):
                name = name_bytes.decode('utf-8')
                if name not in ('.', '..'):
                    all_entries[ino] = name
        pos += rlen

with open('/tmp/inode_map.json', 'r') as f:
    inode_map = {int(k): v for k, v in json.load(f).items()}

def get_path(ino):
    parts = []
    curr = ino
    visited = set()
    while curr in inode_map and curr not in visited:
        visited.add(curr)
        entry = inode_map[curr]
        parts.append(entry['name'])
        curr = entry['parent']
        if curr in (13893633, 2, 0):
            break
    if parts:
        return '/'.join(reversed(parts))
    return None

