# 2. Map and copy files from MAGIC-2
magic2_dir = '/recovered/WINDOW_0753/MAGIC-2'
mapped_count = 0
unmapped_code = 0
for root, dirs, files in os.walk(magic2_dir):
    for f in files:
        m = re.search(r'I_0*([0-9]+)', f)
