                try:
                    shutil.copy2(s_path, dest)
                    unmapped_code += 1
                except:
                    pass

print(f'Done! Successfully restored {mapped_count} files to exact original directory paths!')
print(f'Restored {unmapped_code} named files to RECOVERED_BY_NAME!')
